<?php if (!$rows): ?><div class="card empty-state"><div class="big"><?= e(__('La lista de espera está vacía')) ?></div><p><?= e(__('Cuando alguien se anote porque no hay horarios, aparecerá aquí. Al cancelarse una %s, se ofrece automáticamente al siguiente.', mb_strtolower(term('appt')))) ?></p></div><?php else: ?>
<div class="tbl-wrap"><table class="tbl"><thead><tr><th><?= e(__('Nombre')) ?></th><th><?= e(__('Contacto')) ?></th><th><?= e(__('Servicio')) ?></th><th><?= e(__('Rango')) ?></th><th><?= e(__('Estado')) ?></th><th></th></tr></thead><tbody>
<?php foreach ($rows as $w): ?><tr><td><b><?= e($w['name']) ?></b><br><span class="hint"><?= e(fdate($w['created_at'])) ?></span></td><td>+<?= e($w['phone_cc']) ?> <?= e($w['phone']) ?><br><span class="hint"><?= e($w['email']) ?></span></td>
  <td><?= e($w['service_name']) ?><br><span class="hint"><?= e($w['prof_name'] ?: __('Cualquiera')) ?></span></td><td><?= e(fdate($w['date_from'])) ?> – <?= e(fdate($w['date_to'])) ?></td>
  <td><span class="badge <?= ['offered' => 'badge-warn', 'waiting' => 'badge-gold', 'booked' => 'badge-ok'][$w['status']] ?? '' ?>"><?= e(['offered' => __('Oferta enviada'), 'waiting' => __('En espera'), 'booked' => __('Agendado'), 'expired' => __('Vencido')][$w['status']]) ?></span><?php if ($w['status'] === 'offered'): ?><br><span class="hint"><?= e(fdatetime($w['offer_start'])) ?> · <?= e(__('vence')) ?> <?= e(ftime($w['offer_expires'])) ?></span><?php endif; ?></td>
  <td class="acts"><a class="btn btn-line btn-sm" target="_blank" rel="noopener" href="<?= e(\Aurea\Core\Util::waLink($w['phone_cc'], $w['phone'], 'Hola ' . explode(' ', $w['name'])[0] . ', tenemos disponibilidad para ' . $w['service_name'] . '.')) ?>">WhatsApp</a>
    <?php foreach (['booked' => 'Agendado', 'waiting' => 'Reabrir', 'delete' => 'Quitar'] as $act => $l): ?><form class="inline-form" method="post" action="<?= e(url('/admin/espera/' . $w['id'] . '/accion')) ?>" <?= $act === 'delete' ? 'data-confirm="' . e(__('¿Quitar de la lista?')) . '"' : '' ?>><?= csrf_field() ?><input type="hidden" name="action" value="<?= $act ?>"><button class="btn btn-ghost btn-sm" type="submit"><?= e(__($l)) ?></button></form><?php endforeach; ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
